                path = path.substring(0, pos + 8);
            } else {
                line = -1;
            }
            pos = path.indexOf('@');
            if (pos != -1) { // call by tag
                callTag = path.substring(pos);
                path = path.substring(0, pos);
            } else {
                callTag = null;
