        for (String path : STATIC_RESOURCES) {
            int pos = path.lastIndexOf('/');
            if (pos == -1) {
                copyToFile(path, resFile.getParent() + File.separator + path);
            } else {
                copyToFile(path, resPath + path.substring(pos + 1));
            }
        }
    }

